INSERT INTO MESSAGE (SenderID, ReceiverID, MessageContent, Timestamp) VALUES
(14, 4, 'Good afternoon Dr. Cheung, will we be covering organic chemistry reactions?', '2026-06-12 14:00:00'),
(4, 14, 'Yes Brian! We will go through substitution and addition mechanism questions.', '2026-06-12 14:25:00'),
(15, 6, 'Hi Mr. Ho, thank you for helping me with the SQL database section of my SBA.', '2026-06-08 20:00:00'),
(6, 15, 'You are welcome Chloe! Keep up the good work on your normalized tables.', '2026-06-08 20:15:00'),
(18, 7, 'Hello Ms. Kwok, my daughter Grace wants to improve her BAFS section A marks.', '2026-05-10 09:30:00'),
(7, 18, 'No problem Mrs. Grace! We will do intensive drills on trial balances and ledger entries.', '2026-05-10 10:10:00'),
(34, 12, 'Hi Ms. Fung, can we change our lesson time to 4 PM next Wednesday?', '2026-05-20 16:45:00'),
(12, 34, 'That works for me Leo! See you next Wednesday at 4 PM.', '2026-05-20 17:00:00'),
(35, 24, 'Hello Mr. Tsang, should I print out the physics past papers beforehand?', '2026-05-22 11:20:00'),
(24, 35, 'Yes please! Print out 2021 to 2023 Paper 1A multiple choice questions.', '2026-05-22 11:45:00'),
(37, 26, 'Good morning Dr. Chow, M2 Integration by parts is quite challenging for me.', '2026-05-26 08:30:00'),
(26, 37, 'Don\'t worry Nathan! I have a set of shortcut tricks that will simplify it for you.', '2026-05-26 09:05:00'),
(38, 27, 'Hi Mr. Tang, do you have sample high-scoring essays for DSE English Paper 2?', '2026-05-28 19:15:00'),
(27, 38, 'Yes Olivia! I will share a sample answer bank during our session.', '2026-05-28 19:40:00'),
(40, 29, 'Hello Mr. Chiu, is Python network programming included in our ICT syllabus?', '2026-06-01 13:10:00'),
(29, 40, 'We focus on basic algorithm analysis, pseudocode, and relational database queries.', '2026-06-01 13:35:00'),
(52, 6, 'Hi Mr. Ho, I just submitted a booking request for next Thursday.', '2026-06-10 16:00:00'),
(6, 52, 'Got it Cathy! I will review and confirm it shortly.', '2026-06-10 16:20:00'),
(62, 27, 'Hi Mr. Tang, unfortunately I have a school event and need to cancel our lesson.', '2026-06-20 09:00:00'),
(27, 62, 'Thanks for letting me know Marcus! Let me know when you would like to reschedule.', '2026-06-20 09:15:00');
